   "glossary": [
    {
     "term": "Alternative Investment",
     "def": "An asset outside the traditional stocks/bonds/cash categories — e.g., real estate, partnerships, hedge funds, private placements, commodities, or structured products — typically less liquid and more complex."
    },
    {
     "term": "REIT (Real Estate Investment Trust)",
     "def": "A company that pools capital to own, operate, or finance income-producing real estate; passes income (not losses) to shareholders and must meet the 75/75/90 tests for favorable tax treatment."
    },
    {
     "term": "Equity REIT",
     "def": "A REIT that owns and operates income-producing property, deriving revenue mainly from rents; the most common REIT type."
    },
    {
     "term": "Mortgage REIT",
     "def": "A REIT that lends to property owners or invests in mortgages and mortgage-backed securities, earning revenue mainly from interest; sensitive to interest rates."
    },
    {
     "term": "Non-Traded REIT",
     "def": "An SEC-registered REIT that does not trade on an exchange; illiquid with limited redemptions, high up-front fees, and NAV-based (appraised) pricing."
    },
    {
     "term": "Direct Participation Program (DPP)",
     "def": "A pooled, flow-through investment (usually a limited partnership) that passes income, gains, losses, deductions, and credits directly to investors; pays no entity-level tax."
    },
    {
     "term": "Flow-Through (Pass-Through) Entity",
     "def": "An entity that is not taxed at the business level; its tax items pass directly to the owners, who report them on their individual returns (reported via Schedule K-1)."
    },
    {
     "term": "General Partner (GP)",
     "def": "The partner who manages a limited partnership, makes business decisions, owes a fiduciary duty, and bears UNLIMITED personal liability."
    },
    {
     "term": "Limited Partner (LP)",
     "def": "A passive investor in a partnership whose liability is limited to the amount invested and who has no management role; loses that protection if they actively manage."
    },
    {
     "term": "Intangible Drilling Costs (IDCs)",
     "def": "Deductible, non-salvageable costs of drilling an oil and gas well (labor, fuel, supplies); a major early tax deduction in oil and gas DPPs."
    },
    {
     "term": "Hedge Fund",
     "def": "A privately offered, lightly regulated pool using leverage, short selling, and derivatives to seek absolute returns; sold to accredited investors with lock-ups, gates, and '2 and 20' fees."
    },
    {
     "term": "Fund of Funds (FOF)",
     "def": "A fund that invests in other (often hedge) funds for manager/strategy diversification, at the cost of an extra layer of fees."
    },
    {
     "term": "Private Placement",
     "def": "An unregistered securities offering sold under Regulation D, mainly to accredited investors via a private placement memorandum; the securities are restricted and not freely resalable."
    },
    {
     "term": "Accredited Investor",
     "def": "An investor who meets income (>$200K individual / >$300K joint for two years), net worth (>$1M excluding primary residence), or qualifying professional-credential standards."
    },
    {
     "term": "Regulation D",
     "def": "A Securities Act of 1933 rule providing exemptions from full SEC registration for private placements, primarily to accredited investors."
    },
    {
     "term": "Structured Product",
     "def": "A security whose return is linked to an underlying asset or index via an embedded derivative; usually a debt obligation of the issuer, carrying issuer credit risk."
    },
    {
     "term": "Principal-Protected Note (PPN)",
     "def": "A structured note promising return of principal at maturity plus index-linked upside; the protection depends entirely on the issuer's solvency."
    },
    {
     "term": "Net Asset Value (NAV)",
     "def": "Total assets minus total liabilities, divided by shares outstanding; for non-traded vehicles it is an estimated/appraised value rather than a live market price."
    }
   ],
