   "glossary": [
    {
     "term": "SEC (Securities and Exchange Commission)",
     "def": "The federal government agency created by the Securities Exchange Act of 1934 that oversees the securities markets and supervises the self-regulatory organizations."
    },
    {
     "term": "Self-Regulatory Organization (SRO)",
     "def": "An industry membership body (e.g., FINRA, MSRB, CBOE) empowered by the SEC to write and enforce rules for its members; not a government agency."
    },
    {
     "term": "FINRA",
     "def": "The Financial Industry Regulatory Authority, the largest SRO; regulates broker-dealers and their associated persons and administers the SIE and qualification exams."
    },
    {
     "term": "MSRB",
     "def": "The Municipal Securities Rulemaking Board; writes the rules governing municipal securities but does not enforce them (FINRA and bank regulators enforce)."
    },
    {
     "term": "CBOE (Cboe)",
     "def": "The self-regulatory organization for listed (exchange-traded) options, originally the Chicago Board Options Exchange."
    },
    {
     "term": "SIPC",
     "def": "The Securities Investor Protection Corporation; a nonprofit that protects customers of a failed broker-dealer up to $500,000 per customer, of which a maximum of $250,000 may be cash."
    },
    {
     "term": "Form U4",
     "def": "The Uniform Application for Securities Industry Registration, filed by a member firm via CRD to register an individual; includes disclosure and employment history."
    },
    {
     "term": "Form U5",
     "def": "The Uniform Termination Notice filed by a firm within 30 days of a registered person's termination, stating the reason for departure."
    },
    {
     "term": "CRD (Central Registration Depository)",
     "def": "FINRA's electronic registration and licensing system through which U4/U5 forms are filed and which feeds BrokerCheck."
    },
    {
     "term": "Statutory Disqualification",
     "def": "A status that bars a person from associating with a member firm, triggered by events such as a felony (or securities/money misdemeanor) conviction within 10 years or an SRO/SEC bar."
    },
    {
     "term": "SIE Exam",
     "def": "The Securities Industry Essentials exam; a foundational test that requires no firm sponsorship, is open to anyone 18+, and whose result is valid for four years."
    },
    {
     "term": "Top-Off (Qualification) Exam",
     "def": "A representative-level exam (e.g., Series 7, Series 6) that, combined with the SIE, qualifies a person to transact business; requires firm sponsorship."
    },
    {
     "term": "Regulatory Element",
     "def": "The FINRA-administered, standardized continuing-education requirement that registered persons must complete annually."
    },
    {
     "term": "Firm Element",
     "def": "The annual continuing-education program designed and delivered by the member firm, tailored to its products and its covered registered persons."
    },
    {
     "term": "Retail Communication",
     "def": "Any written/electronic communication made available to more than 25 retail investors in a 30-day period; generally requires principal approval before first use."
    },
    {
     "term": "Correspondence",
     "def": "Written communication distributed to 25 or fewer retail investors within a 30-day period; subject to supervision but not prior principal approval."
    },
    {
     "term": "Private Securities Transaction (PST)",
     "def": "A securities transaction outside the scope of a rep's employment; requires prior written notice and, if the rep is compensated, written firm approval and recording ('selling away' if done without notice)."
    },
    {
     "term": "Code of Procedure",
     "def": "FINRA's disciplinary process for handling alleged rule violations and imposing sanctions such as fines, suspensions, expulsion, and bars."
    },
    {
     "term": "Code of Arbitration Procedure",
     "def": "FINRA's process for resolving monetary disputes between members, reps, and customers; decisions are final and binding with very limited appeal."
    },
    {
     "term": "Rule 4530",
     "def": "FINRA's reporting rule requiring members to report specified events (e.g., regulatory actions, certain customer complaints, felonies) within 30 days, plus quarterly complaint statistics."
    }
   ],
